import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { api, requestId } from './api';
import type { Session } from './api';
import { Icon, Orb } from './icons';
import Workers from './Workers';
import { Modal } from './Modal';
import { emptyInputContext, inputSummary, TaskContextDialog, TaskRunCard } from './TaskContext';
import { DiagnosticsPanel, diagnosticConnectionLabel, useDiagnostics } from './Diagnostics';
import type { DiagnosticsView } from './Diagnostics';
import { ApprovalSummary, effectiveApprovalStatus, ManagementDialog } from './Management';
import type { ManagementTab } from './Management';
import type { IconName } from './icons';
import type { Approval, Artifact, Bootstrap, Conversation, Goal, InputContext, Memory, Message, Run, Settings, Runtime } from './types';

type Page = 'workers' | 'chat' | 'activity' | 'ideas' | 'goals' | 'library';
type Route = { page: Page; id?: string };
type Dialog = { type: 'context'; conversationId?: string; goalId?: string } | { type: 'management'; tab: ManagementTab } | { type: 'settings' } | { type: 'search' } | { type: 'category'; category: Category } | { type: 'rename'; conversation: Conversation } | { type: 'delete'; kind: 'conversation' | 'memory' | 'goal'; id: string; title: string } | { type: 'note'; memory?: Memory } | null;
type Category = { title: string; icon: IconName; label: string; description: string; prompt: string };
const categories: Category[] = [
  { title: '市场开发', icon: 'work', label: '市场开发', description: '确定目标买手画像、市场筛选标准和可执行的线索开发计划。', prompt: '我想开发一个新市场。请帮助定义目标客户、任务成果和预算，再考虑是否委托 AI Worker。' },
  { title: '渠道拓展', icon: 'people', label: '渠道拓展', description: '研究海外经销商、批发商和适合的销售渠道。', prompt: '我们想开拓海外分销渠道。请制定渠道验证方案，并明确哪些工作可以委托专业 Worker。' },
  { title: '销售转化', icon: 'goals', label: '销售转化', description: '把客户询盘、跟进和报价变成可检查的流程。', prompt: '我们想改善外贸询盘转化率。请拆解可量化的改进目标和待审批的执行任务。' },
  { title: '品牌设计', icon: 'palette', label: '品牌设计', description: '创建可审核的销售素材、产品介绍和站点内容。', prompt: '我们需要为产品制作海外销售素材。先明确素材清单、证据要求和验收方式。' },
  { title: '电商验证', icon: 'laptop', label: '电商验证', description: '验证产品在选定电商渠道的实际销售机会。', prompt: '我们希望验证一个产品在跨境电商渠道是否值得投入，请设计低成本验证计划。' },
  { title: '业务效率', icon: 'bolt', label: '业务效率', description: '减少重复性业务工作，设计可以交给 Worker 的标准流程。', prompt: '我们想降低企业日常业务的重复性工作，请帮助识别适合交给 AI Worker 的任务，并确定验收标准。' },
  { title: '其他增长', icon: 'sparkle', label: '其他增长', description: '任何具体业务成果都可以先定义为可委托任务。', prompt: '我们有一个企业增长目标。请先明确成果、范围、预算及权限，不要直接执行未经批准的外部操作。' },
];
const pageLabels: Record<Page, string> = { workers: 'AI Worker', chat: '聊天', activity: '动态', ideas: '灵感', goals: '目标', library: '资料库' };
const statusLabels: Record<string, string> = { draft: '待开始', running: '进行中', awaiting_approval: '待审批', paused: '已暂停', blocked: '等待连接', completed: '已审核', review_required: '待审核', cancelled: '已取消', failed: '需要重试', idle: '就绪' };
const defaultSettings: Settings = { name: 'Workspace', language: 'zh', model: 'deepseek-flash', maxGoalSteps: 3 };
function routePath() { return location.protocol === 'file:' ? location.hash.replace(/^#/, '') || '/workers' : location.pathname; }
function readRoute(): Route { const [page, id] = routePath().split('/').filter(Boolean); return { page: ['workers', 'chat', 'activity', 'ideas', 'goals', 'library'].includes(page) ? page as Page : 'workers', id }; }
function formatTime(date: string) { return new Date(date).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false }); }
function formatDate(date: string) { const d = new Date(date); const today = new Date(); if (d.toDateString() === today.toDateString()) return '今天'; const yesterday = new Date(today); yesterday.setDate(today.getDate() - 1); if (d.toDateString() === yesterday.toDateString()) return '昨天'; return d.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' }); }
function sortNewest<T extends { updatedAt?: string; createdAt: string }>(items: T[]) { return [...items].sort((a, b) => new Date(b.updatedAt || b.createdAt).getTime() - new Date(a.updatedAt || a.createdAt).getTime()); }
function errorText(error: unknown) { return error instanceof Error ? error.message : '操作未完成，请稍后重试'; }
function approvalThread(approval: Approval) { const payload = approval.payload as { binding?: { conversationId?: string; runId?: string } } | null; return payload?.binding?.runId ? payload.binding.conversationId : undefined; }
function Status({ value }: { value: string }) { return <span className={`status status-${value}`}><i />{statusLabels[value] || value}</span>; }
function IconButton({ icon, label, onClick, className = '', disabled = false }: { icon: IconName; label: string; onClick: () => void; className?: string; disabled?: boolean }) { return <button type="button" className={`icon-button ${className}`} aria-label={label} title={label} onClick={onClick} disabled={disabled}><Icon name={icon} size={20} /></button>; }
function EmptyState({ icon, title, description, children, compact = false }: { icon: IconName; title: string; description: string; children?: ReactNode; compact?: boolean }) { return <div className={`empty-state ${compact ? 'compact' : ''}`}><span className="empty-icon"><Icon name={icon} size={compact ? 24 : 31} /></span><h3>{title}</h3><p>{description}</p>{children}</div>; }
function MessageContent({ content }: { content: string }) {
  const parts = content.split(/(```[\s\S]*?```)/g);
  return <div className="message-content">{parts.map((part, i) => part.startsWith('```') ? <pre key={i}><code>{part.replace(/^```[^\n]*\n?/, '').replace(/```$/, '')}</code></pre> : <span key={i}>{part.split(/(\*\*[^*]+\*\*)/g).map((text, j) => text.startsWith('**') && text.endsWith('**') ? <strong key={j}>{text.slice(2, -2)}</strong> : text)}</span>)}</div>;
}

export default function App({ session, onLogout }: { session: Session; onLogout: () => Promise<void> }) {
  const readOnly = session.user?.role === 'viewer';
  const [route, setRoute] = useState<Route>(readRoute);
  const [data, setData] = useState<Bootstrap | null>(null);
  const [loading, setLoading] = useState(true);
  const { view: diagnostics, begin: beginRead, accept: acceptDiagnostics, fail: failDiagnostics } = useDiagnostics();
  const [busy, setBusy] = useState(false);
  const [dialog, setDialog] = useState<Dialog>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [panelOpen, setPanelOpen] = useState(true);
  const [panelTab, setPanelTab] = useState('activity');
  const [draft, setDraft] = useState('');
  const [draftContext, setDraftContext] = useState<InputContext>(emptyInputContext);
  const [taskMode, setTaskMode] = useState(false);
  const [conversationSearch, setConversationSearch] = useState('');
  const [toast, setToast] = useState<{ message: string; error: boolean } | null>(null);
  const [composerMenu, setComposerMenu] = useState(false);
  const [goalFilter, setGoalFilter] = useState('all');
  const [libraryFilter, setLibraryFilter] = useState('all');
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const sendingRef = useRef(false);
  const bootstrapLock = useRef<Promise<void> | null>(null);
  const mutationLock = useRef(false);
  const navigationRevision = useRef(0);
  const currentDialog = useRef(dialog); currentDialog.current = dialog;
  const pendingSendRef = useRef<{ conversationId: string; content: string; requestId: string; contextKey: string } | null>(null);
  const settings = data?.settings || defaultSettings;
  const conversations = useMemo(() => sortNewest(data?.conversations || []), [data?.conversations]);
  const selectedConversation = conversations.find(c => c.id === route.id);
  const selectedContext = selectedConversation ? selectedConversation.inputContext : draftContext;
  const contextConversation = dialog?.type === 'context' ? conversations.find(c => c.id === dialog.conversationId) : undefined;
  const messages = (data?.messages || []).filter(m => m.conversationId === route.id);
  const selectedGoal = route.page === 'goals' && route.id ? data?.goals.find(g => g.id === route.id) : undefined;
  const chatGoal = route.page === 'chat' && route.id ? data?.goals.find(g => g.conversationId === route.id) : undefined;
  const running = ['running', 'awaiting_approval'].includes(selectedConversation?.status || '') || messages.some(m => m.status === 'pending');
  const closeDialog = useCallback(() => { navigationRevision.current++; setDialog(null); }, []);
  const notify = useCallback((message: string, error = false) => setToast({ message, error }), []);
  const refresh = useCallback((_silent = false): Promise<void> => {
    if (bootstrapLock.current) return bootstrapLock.current;
    const ticket = beginRead();
    const pending = (async () => {
      try {
        const result = await api<Bootstrap>('/bootstrap');
        if (!acceptDiagnostics(result.diagnostics, ticket)) return;
        setData(previous => previous && previous.diagnostics?.instanceId === result.diagnostics?.instanceId && (previous.meta?.sequence || 0) > (result.meta?.sequence || 0) ? previous : result);
      } catch (error) { failDiagnostics(error, ticket); }
      finally { bootstrapLock.current = null; setLoading(false); }
    })();
    bootstrapLock.current = pending; return pending;
  }, [beginRead, acceptDiagnostics, failDiagnostics]);
  useEffect(() => { void refresh(); const interval = window.setInterval(() => void refresh(true), 2000); return () => clearInterval(interval); }, [refresh]);
  useEffect(() => { const onPop = () => { navigationRevision.current++; setRoute(readRoute()); setDraft(''); setTaskMode(false); setDialog(null); setComposerMenu(false); }; window.addEventListener('popstate', onPop); window.addEventListener('hashchange', onPop); return () => { window.removeEventListener('popstate', onPop); window.removeEventListener('hashchange', onPop); }; }, []);
  useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(null), 3600); return () => clearTimeout(timer); } }, [toast]);
  useEffect(() => { document.title = `${pageLabels[route.page]} · Workspace`; }, [route.page]);
  useEffect(() => { const element = scrollRef.current; if (element) element.scrollTop = element.scrollHeight; }, [route.id, messages.length, messages[messages.length - 1]?.content]);
  useEffect(() => { const el = inputRef.current; if (el) { el.style.height = '24px'; el.style.height = `${Math.min(el.scrollHeight, 144)}px`; } }, [draft]);
  useEffect(() => { const handler = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); setDialog({ type: 'search' }); } if (e.key === 'Escape') { setComposerMenu(false); if (window.innerWidth < 760) setSidebarOpen(false); } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler); }, []);
  function navigate(page: Page, id?: string) { navigationRevision.current++; setDialog(null); if (page === 'chat' && (route.page !== 'chat' || route.id !== id)) { setDraft(''); setTaskMode(false); if (!id) setDraftContext(emptyInputContext()); } const path = `/${page}${id ? `/${id}` : ''}`; if (routePath() !== path) { if (location.protocol === 'file:') location.hash = path; else history.pushState({}, '', path); } setRoute({ page, id }); setComposerMenu(false); if (window.innerWidth < 760) setSidebarOpen(false); }
  async function mutate<T>(path: string, method: string, body?: unknown): Promise<T | undefined> {
    if (readOnly) { notify('当前账号只有读取权限', true); return undefined; }
    if (mutationLock.current || sendingRef.current) return undefined;
    mutationLock.current = true; setBusy(true);
    const revision = navigationRevision.current, openedDialog = currentDialog.current;
    try { const result = await api<T>(path, method, body); await refresh(true); return revision === navigationRevision.current && openedDialog === currentDialog.current ? result : undefined; }
    catch (error) { notify(errorText(error), true); return undefined; }
    finally { mutationLock.current = false; setBusy(false); }
  }
  async function newConversation(title?: string) { const result = await mutate<{ conversation: Conversation }>('/conversations', 'POST', { title }); if (result) { navigate('chat', result.conversation.id); setDraft(''); setTimeout(() => inputRef.current?.focus(), 30); } return result?.conversation; }
  async function sendMessage(e?: FormEvent) {
    e?.preventDefault(); if (readOnly || !draft.trim() || busy || running || sendingRef.current || mutationLock.current) return;
    const content = draft.trim(), inputContext = selectedContext, workspaceExecution = taskMode;
    const contextKey = JSON.stringify({ inputContext, workspaceExecution }); let revision = navigationRevision.current;
    sendingRef.current = true; setBusy(true);
    try {
      const previous = pendingSendRef.current;
      let id = selectedConversation?.id || (previous?.content === content && previous.contextKey === contextKey && (!route.id || route.id === previous.conversationId) ? previous.conversationId : undefined);
      if (!id) { const result = await api<{ conversation: Conversation }>('/conversations', 'POST', { inputContext }); id = result.conversation.id; if (revision === navigationRevision.current) { navigate('chat', id); revision = navigationRevision.current; } }
      const retryId = previous?.conversationId === id && previous.content === content && previous.contextKey === contextKey ? previous.requestId : requestId();
      pendingSendRef.current = { conversationId: id, content, requestId: retryId, contextKey };
      await api(`/conversations/${id}/messages`, 'POST', { content, requestId: retryId, ...(inputContext ? { inputContext } : {}), workspaceExecution });
      pendingSendRef.current = null; if (revision === navigationRevision.current) setDraft(''); await refresh(true);
    } catch (error) { if (revision === navigationRevision.current) setDraft(content); notify(errorText(error), true); await refresh(true); }
    finally { sendingRef.current = false; setBusy(false); if (revision === navigationRevision.current) inputRef.current?.focus(); }
  }
  async function beginCategory(category: Category) { if (readOnly || mutationLock.current) return; mutationLock.current = true; const revision = navigationRevision.current; setBusy(true); try { const { conversation } = await api<{ conversation: Conversation }>('/conversations', 'POST', { title: category.label ? `我的${category.label}目标` : '我的新目标' }); await api('/goals', 'POST', { title: category.label ? `我的${category.label}目标` : '我的新目标', description: '', conversationId: conversation.id, maxSteps: settings.maxGoalSteps }); await refresh(true); if (revision !== navigationRevision.current) return; setDialog(null); navigate('chat', conversation.id); setDraft(category.prompt); setTimeout(() => inputRef.current?.focus(), 50); } catch (error) { notify(errorText(error), true); } finally { mutationLock.current = false; setBusy(false); } }
  async function goalAction(goal: Goal, action: string) { const result = await mutate(`/goals/${goal.id}`, 'PATCH', { action, requestId: requestId() }); if (result) notify({ start: '目标已提交，进展会出现在动态里', pause: '目标已暂停', resume: '已继续推进目标', cancel: '目标已取消', complete: '目标成果已标记为已审核' }[action] || '已更新目标'); }
  async function saveMessage(message: Message) { const result = await mutate('/artifacts', 'POST', { filename: `Workspace-${message.id}.md`, title: '聊天回复', content: message.content, sourceConversationId: message.conversationId, ...(message.runId ? { sourceRunId: message.runId } : {}), requestId: `message-${message.id}` }); if (result) notify('已保存为 Markdown 文件，可在资料库的文件产物中下载'); }
  async function runDecision(run: Run, proposalId: string, decision: 'approved' | 'denied') { const result = await mutate(`/runs/${run.id}/action-decision`, 'POST', { proposalId, decision, confirmed: true }); if (result) notify(decision === 'approved' ? '已批准具体动作，请点击继续后执行' : '已拒绝动作，本次任务已停止，未执行动作'); }
  async function resumeRun(run: Run) { const result = await mutate(`/runs/${run.id}/resume`, 'POST', { requestId: requestId() }); if (result) notify('已按确认范围继续，请查看执行回执'); }
  async function copy(text: string) { try { await navigator.clipboard.writeText(text); notify('已复制'); } catch { notify('浏览器暂不支持复制，请手动选择文字', true); } }
  function exportMemory(memory: Memory) { const url = URL.createObjectURL(new Blob([memory.content], { type: 'text/markdown;charset=utf-8' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `Workspace-${memory.id.slice(0, 8)}.md`; anchor.click(); URL.revokeObjectURL(url); notify('已导出 Markdown 文件'); }
  function applyPrompt(prompt: string) { navigate('chat'); setDraft(prompt); setTimeout(() => inputRef.current?.focus(), 30); }
  const recentActivity = sortNewest(data?.activity || []);
  const pendingApprovals = (data?.capabilities?.approvals || []).filter(item => effectiveApprovalStatus(item) === 'pending');
  const activeGoals = sortNewest(data?.goals || []).filter(g => !['completed', 'cancelled', 'review_required'].includes(g.status));

  return <div className={`app-shell ${route.page === 'chat' ? 'chat-route' : ''} ${panelOpen ? 'with-panel' : ''} ${sidebarOpen ? 'with-sidebar' : ''}`}>
    <aside className="nav-rail" aria-label="主导航">
      {route.page !== 'chat' && <button className="brand-button" onClick={() => navigate('workers')} aria-label="Workspace 首页" title="Workspace"><Orb small /></button>}
      <nav className="rail-middle">{([{ page: 'workers', icon: 'work' }, { page: 'activity', icon: 'activity' }, { page: 'goals', icon: 'goals' }, { page: 'library', icon: 'library' }, { page: 'search', icon: 'search' }, { page: 'chat', icon: 'chat' }] as { page: string; icon: IconName }[]).map(item => <button key={item.page} className={`rail-button ${route.page === item.page ? 'active' : ''}`} onClick={() => item.page === 'search' ? setDialog({ type: 'search' }) : navigate(item.page as Page)} aria-label={item.page === 'search' ? '搜索' : pageLabels[item.page as Page]} aria-current={route.page === item.page ? 'page' : undefined}><Icon name={item.icon} size={24} /><span className="nav-tooltip">{item.page === 'search' ? '搜索' : pageLabels[item.page as Page]}</span></button>)}</nav>
      <div className="rail-bottom"><button className="rail-button download-placeholder" aria-label="下载客户端（暂未提供）" title="当前为本地网页版本，暂未提供独立客户端" disabled><Icon name="download" size={24} /><span className="nav-tooltip">暂未提供独立客户端</span></button><button className="rail-button" onClick={() => setDialog({ type: 'settings' })} aria-label="设置"><Icon name="menu" size={24} /><span className="nav-tooltip">设置</span></button></div>
    </aside>

    {route.page === 'chat' && sidebarOpen && <><div className="drawer-shade" onClick={() => setSidebarOpen(false)} /><aside className="conversation-sidebar"><div className="sidebar-top"><label className="small-search"><Icon name="search" size={17} /><input aria-label="搜索聊天记录" placeholder="搜索" value={conversationSearch} onChange={e => setConversationSearch(e.target.value)} /></label><IconButton icon="more" label="收起聊天列表" onClick={() => setSidebarOpen(false)} /></div>{conversations.length > 0 && <button className="new-chat" onClick={() => void newConversation()} disabled={busy || readOnly}><Icon name="plus" size={18} />新聊天</button>}<div className={`conversation-list ${!conversations.length ? 'empty-conversation-list' : ''}`}>{conversations.filter(c => c.title.toLowerCase().includes(conversationSearch.toLowerCase())).map(c => <div key={c.id} className={`conversation-item ${route.id === c.id ? 'selected' : ''}`}><button className="conversation-select" onClick={() => navigate('chat', c.id)}><span>{c.title || '新聊天'}</span><small>{formatDate(c.updatedAt)}</small></button><div className="conversation-actions"><IconButton icon="edit" label={`重命名 ${c.title}`} onClick={() => setDialog({ type: 'rename', conversation: c })} /><IconButton icon="trash" label={`删除 ${c.title}`} onClick={() => setDialog({ type: 'delete', kind: 'conversation', id: c.id, title: c.title })} /></div></div>)}{!conversations.length && <div className="side-chat-empty"><Icon name="chats" size={31} /><h3>发起旁聊</h3><p>旁聊是按主题整理对话的可选方式。</p><button className="side-chat-start" onClick={() => void newConversation()} disabled={busy || readOnly}>新旁聊</button></div>}{conversations.length > 0 && !conversations.some(c => c.title.toLowerCase().includes(conversationSearch.toLowerCase())) && <p className="no-results">没有找到相关聊天</p>}</div></aside></>}

    <main className={`main-content ${route.page !== 'chat' ? 'document-view' : ''}`}>
      {['disconnected', 'stale', 'reconnected', 'restarted'].includes(diagnostics.state) && <div className="connection-banner" role={diagnostics.state === 'disconnected' ? 'alert' : 'status'}><Icon name="info" size={16} /><span>{diagnosticConnectionLabel(diagnostics)}{diagnostics.state === 'disconnected' || diagnostics.state === 'stale' ? ` · ${diagnostics.snapshot ? '显示上次快照' : '尚无可用快照'}，请检查网络与服务进程` : diagnostics.state === 'restarted' ? ' · 请检查中断运行，中断运行不会自动重放' : ' · 已更新服务快照，模型在线验收仍需单独完成'}</span><button type="button" onClick={() => void diagnostics.refresh()} disabled={diagnostics.checking}>刷新诊断</button></div>}
      {route.page === 'chat' ? <>
        <header className="chat-header"><button className="chat-title-pill" onClick={() => setSidebarOpen(!sidebarOpen)} aria-expanded={sidebarOpen}><Icon name="menu" size={19} /><span>{selectedConversation?.title || '聊天'}</span></button>{!panelOpen && <button className="floating-assistant" aria-label="显示助手面板" onClick={() => setPanelOpen(true)}><Orb small /><span>{settings.name}</span></button>}<div className="header-actions">{route.id && <IconButton icon="plus" label="新建聊天" onClick={() => { navigate('chat'); setDraft(''); }} />}<button className="invite-pill" aria-label="邀请（此版本暂未提供）" title="此本地版本暂未提供多人邀请" disabled><Icon name="gift" size={17} /><span>邀请</span></button></div></header>
        {chatGoal && <div className="chat-goal-strip"><button onClick={() => navigate('goals', chatGoal.id)}><Icon name="goals" size={17} /><span>{chatGoal.title}</span><Status value={chatGoal.status} /><Icon name="chevron" size={14} /></button></div>}
        <div className={`message-scroll ${!messages.length ? 'is-empty' : ''}`} ref={scrollRef}>
          {loading ? <div className="loading-state"><span className="loading-dot" />正在打开你的空间</div> : !messages.length ? <div className="welcome-conversation"><div className="message-timestamp">新的开始</div><div className="intro-bubble"><p>{chatGoal ? `嗨，我是 ${settings.name}。先聊聊你想改变什么、为什么重要，我们一起把这个目标变得具体，再按你的节奏推进。` : `嗨，我是 ${settings.name}，你的企业协作助手。我可以帮你梳理业务问题、明确成果和验收标准，真正执行请通过 AI Worker 委托。`}</p><span className="sr-only">助手介绍</span></div>{!chatGoal && <div className="intro-bubble starter-bubble"><p>今天想先聊点什么？</p><div className="starter-prompts"><button onClick={() => setDraft('帮我理清今天最值得做的三件事。')}><span>理清今天的重点</span></button><button onClick={() => navigate('goals')}><span>开始一个新目标</span></button><button onClick={() => setDraft('我有一个想法，想和你一起探索。')}><span>聊聊一个想法</span></button></div></div>}</div> : <div className="messages">{messages.map((message, index) => <div key={message.id} className={`message-row ${message.role} message-${message.status || 'complete'}`}>{(index === 0 || new Date(message.createdAt).getTime() - new Date(messages[index - 1].createdAt).getTime() > 300000) && <div className="message-timestamp">{formatDate(message.createdAt)} {formatTime(message.createdAt)}</div>}<div className="message-bubble">{message.status === 'pending' ? <div className="thinking"><span /><span /><span /><span className="thinking-label">正在思考</span></div> : <MessageContent content={message.content} />}{message.error?.message && <p className="field-help" role="status">{message.error.message}</p>}{['blocked', 'failed'].includes(message.status || '') && <button className="inline-setting" onClick={() => message.error?.code === 'SETUP_REQUIRED' ? setDialog({ type: 'settings' }) : setDraft(messages.find(m => m.role === 'user' && m.requestId === message.requestId)?.content || [...messages].reverse().find(m => m.role === 'user')?.content || '')}><Icon name={message.error?.code === 'SETUP_REQUIRED' ? 'settings' : 'refresh'} size={14} />{message.error?.code === 'SETUP_REQUIRED' ? '查看连接设置' : '重新编辑并发送'}</button>}</div>{message.role === 'assistant' && message.status === 'complete' && <div className="message-tools"><IconButton icon="copy" label="复制回复" onClick={() => void copy(message.content)} /><IconButton icon="bookmark" label="保存回复到资料库" onClick={() => void saveMessage(message)} /></div>}</div>)}</div>}
          {data && route.id && (data.runs || []).filter(run => run.conversationId === route.id).map(run => <TaskRunCard key={run.id} run={run} data={data} role={session.user?.role || 'viewer'} busy={busy} onDecision={(item, proposalId, decision) => void runDecision(item, proposalId, decision)} onResume={item => void resumeRun(item)} onCancel={item => void mutate(`/runs/${item.id}/cancel`, 'POST', {})} />)}
        </div>
        <div className="composer-region"><div className="composer-context-row"><button type="button" aria-label="选择任务输入" onClick={() => setDialog({ type: 'context', conversationId: route.id })} disabled={loading || busy || !!running}>任务输入 · {inputSummary(selectedContext)}</button><label><input type="checkbox" aria-label="生成计划与文件草稿" checked={taskMode} onChange={event => setTaskMode(event.target.checked)} disabled={readOnly || busy || !!running} />生成计划与文件草稿</label></div>{running && <button className="stop-generation" onClick={() => void mutate(`/conversations/${route.id}/cancel`, 'POST', {})} disabled={busy || readOnly}><Icon name="stop" size={14} />停止生成</button>}<form className={`composer ${running ? 'composer-running' : ''}`} onSubmit={sendMessage}><div className="composer-left"><IconButton icon="plus" label="更多操作" onClick={() => setComposerMenu(!composerMenu)} />{composerMenu && <div className="composer-popover"><button type="button" onClick={() => { setDialog({ type: 'context', conversationId: route.id }); setComposerMenu(false); }}><Icon name="file" size={17} />选择任务输入</button><button type="button" onClick={() => { navigate('goals'); setComposerMenu(false); }}><Icon name="goals" size={17} />创建目标</button><button type="button" onClick={() => { void newConversation(); setComposerMenu(false); }}><Icon name="chat" size={17} />新建聊天</button><button type="button" onClick={() => { setDialog({ type: 'note' }); setComposerMenu(false); }}><Icon name="bookmark" size={17} />保存笔记</button></div>}</div><textarea ref={inputRef} value={draft} onChange={e => setDraft(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); void sendMessage(); } }} placeholder={chatGoal ? '说说你想实现的目标…' : '消息'} aria-label="输入消息" rows={1} maxLength={20000} disabled={loading} /><button type="submit" className={`send-button ${!draft.trim() ? 'empty-composer-action' : ''}`} aria-label={draft.trim() ? '发送消息' : '语音输入（暂未提供）'} title={draft.trim() ? '发送消息' : '暂未接入语音，请输入文字'} disabled={readOnly || !draft.trim() || busy || !!running || loading}><Icon name={draft.trim() ? 'arrow' : 'microphone'} size={20} /></button></form></div>
      </> : <>
        {route.page !== 'workers' && <header className="page-mobile-header"><span>{pageLabels[route.page]}</span><span className="workspace-wordmark">WORKSPACE</span></header>}
        <div className={`page-content page-${route.page}`}>
          {route.page === 'workers' && <Workers role={session.user?.role || 'viewer'} />}
          {route.page === 'goals' && <><div className="page-heading"><span className="eyebrow">让增长任务，有明确方向</span><h1>业务目标</h1><p>围绕市场、渠道与销售定义成果和预算。业务执行通过 AI Worker 服务任务单完成。</p></div>{!!data?.goals.length && <section className="existing-goals"><div className="section-heading"><h2>我的目标</h2><div className="text-tabs">{[['all', '全部'], ['active', '进行中'], ['completed', '已结束']].map(([key, label]) => <button key={key} className={goalFilter === key ? 'selected' : ''} onClick={() => setGoalFilter(key)}>{label}</button>)}</div></div>{sortNewest(data.goals).filter(g => goalFilter === 'all' || (goalFilter === 'active' ? !['completed', 'cancelled', 'review_required'].includes(g.status) : ['completed', 'cancelled', 'review_required'].includes(g.status))).map(goal => <button className="goal-list-item" key={goal.id} onClick={() => navigate('goals', goal.id)}><span className="goal-list-icon"><Icon name="goals" size={22} /></span><span className="goal-list-copy"><strong>{goal.title}</strong><small>{goal.description || '还在酝酿中，聊聊你的具体想法'}</small></span><Status value={goal.status} /><Icon name="chevron" size={16} /></button>)}{!data.goals.some(g => goalFilter === 'all' || (goalFilter === 'active' ? !['completed', 'cancelled', 'review_required'].includes(g.status) : ['completed', 'cancelled', 'review_required'].includes(g.status))) && <p className="filter-empty">这里还没有目标</p>}</section>}<section className="goal-categories"><h2>创建目标</h2>{categories.map(category => <button className="category-row" key={category.title} onClick={() => setDialog({ type: 'category', category })}><Icon name={category.icon} size={23} /><span>{category.title}</span><Icon name="chevron" size={15} /></button>)}</section><p className="quiet-footnote"><Icon name="shield" size={14} />目标用来规划业务，第三方执行仍需在 AI Worker 中独立授权。</p></>}
          {route.page === 'activity' && <><div className="page-heading"><span className="eyebrow">事情在慢慢发生</span><h1>动态</h1><p>对话、目标和保存的想法，都在这里留下足迹。</p><button className="text-button management-page-link" onClick={() => setDialog({ type: 'management', tab: 'runs' })}><Icon name="activity" size={16} />查看运行记录</button></div>{recentActivity.length ? <ActivityList activity={recentActivity} onOpen={(conversationId, goalId) => goalId ? navigate('goals', goalId) : conversationId ? navigate('chat', conversationId) : undefined} /> : <EmptyState icon="activity" title="还没有新的动态" description="开始一次对话或创建一个目标，之后的每一步都能在这里找到。"><button className="secondary-button" onClick={() => navigate('chat')}>去聊一聊<Icon name="chevron" size={14} /></button></EmptyState>}</>}
          {route.page === 'ideas' && <><div className="page-heading"><span className="eyebrow">留一点空间给好奇心</span><h1>灵感</h1><p>不知道从哪里开始？一个好问题，就能打开新的可能。</p></div><div className="ideas-intro"><span className="ideas-art"><Icon name="ideas" size={40} /></span><div><h2>你想到哪里，我们就聊到哪里</h2><p>这些问题只是起点。选一个，把它变成你自己的想法。</p></div></div>{[{ title: '让日常轻一点', items: ['帮我理清今天最值得做的三件事。', '我总觉得时间不够用，帮我找到可以调整的地方。', '帮我把脑子里零散的待办整理成一个清晰的计划。'] }, { title: '给自己一个新方向', items: ['我想开始学习一项新技能，帮我找到适合的入门路径。', '我有一个还不成熟的想法，想和你一起探索。', '问我几个问题，帮我发现最近真正想做的事。'] }, { title: '把想法变成下一步', items: ['帮我把一个大目标拆成这周就能开始的小行动。', '我想回顾一下最近的进展，找到下一步的重点。'] }].map(section => <section className="idea-section" key={section.title}><h2>{section.title}</h2>{section.items.map(prompt => <button className="idea-row" key={prompt} onClick={() => applyPrompt(prompt)}><span>{prompt}</span><Icon name="arrow" size={17} /></button>)}</section>)}</>}
          {route.page === 'library' && <><div className="page-heading heading-with-action"><div><span className="eyebrow">值得留下的，都放在这里</span><h1>资料库</h1><p>保存好想法、对话中的答案，和你希望助手记住的事。</p></div><button className="secondary-button" onClick={() => setDialog({ type: 'note' })}><Icon name="plus" size={16} />新建笔记</button></div><button className="text-button management-page-link" onClick={() => setDialog({ type: 'management', tab: 'artifacts' })}><Icon name="file" size={16} />文件产物与版本 ({data?.artifacts?.length || 0})</button><div className="library-tabs text-tabs">{[['all', '全部'], ['saved', '保存的内容'], ['preference', '记忆']].map(([key, label]) => <button className={libraryFilter === key ? 'selected' : ''} key={key} onClick={() => setLibraryFilter(key)}>{label}</button>)}</div>{data?.memories.filter(m => libraryFilter === 'all' || (libraryFilter === 'saved' ? m.category === 'saved' : m.category !== 'saved')).length ? <div className="library-grid">{sortNewest(data.memories).filter(m => libraryFilter === 'all' || (libraryFilter === 'saved' ? m.category === 'saved' : m.category !== 'saved')).map(memory => <article className="library-item" key={memory.id}><div className="library-item-top"><span><Icon name={memory.category === 'saved' ? 'bookmark' : 'fingerprint'} size={16} />{memory.category === 'saved' ? '保存的内容' : '记忆'}</span><small>{formatDate(memory.createdAt)}</small></div><button className="library-content-button" onClick={() => setDialog({ type: 'note', memory })}><MessageContent content={memory.content} /></button><p className="memory-scope-label">{memory.category === 'saved' ? '仅保存，不自动加入模型上下文' : `${memory.enabled === false ? '已停用' : '已启用'} · ${memory.conversationId ? `仅聊天：${data.conversations.find(c => c.id === memory.conversationId)?.title || '原聊天已移除'}` : '整个空间'}`}</p><div className="library-item-footer"><button onClick={() => setDialog({ type: 'note', memory })}>查看与编辑<Icon name="chevron" size={13} /></button><div><IconButton icon="copy" label="复制笔记" onClick={() => void copy(memory.content)} /><IconButton icon="download" label="导出笔记" onClick={() => exportMemory(memory)} /><IconButton icon="trash" label="删除笔记" onClick={() => setDialog({ type: 'delete', kind: 'memory', id: memory.id, title: '这条笔记' })} /></div></div></article>)}</div> : <EmptyState icon="library" title="给好想法一个位置" description="在聊天中保存一条回复，或写下你想留住的内容。下次需要时，它就在这里。"><button className="secondary-button" onClick={() => setDialog({ type: 'note' })}><Icon name="plus" size={15} />记下第一个想法</button></EmptyState>}</>}
        </div>
      </>}
    </main>

    {route.page === 'chat' && panelOpen && <aside className="assistant-panel"><IconButton icon="close" label="收起助手面板" onClick={() => setPanelOpen(false)} className="panel-close" /><div className="assistant-profile"><button className="profile-avatar" onClick={() => setDialog({ type: 'settings' })} aria-label="编辑助手设置"><Orb /><span className="avatar-edit"><Icon name="edit" size={14} /></span></button><h2>{settings.name}</h2><button className={`connection-state ${data?.runtime.configured && !['disconnected', 'stale'].includes(diagnostics.state) ? 'connected' : ''}`} onClick={() => setDialog({ type: 'settings' })}><span className="connection-dot"><Icon name="bolt" size={10} /></span>{['disconnected', 'stale'].includes(diagnostics.state) ? diagnosticConnectionLabel(diagnostics) : data?.runtime.configured ? '模型已配置 · 待验证' : '等待配置模型'}</button></div><div className="panel-tabs" role="tablist" aria-label="助手面板">{([{ key: 'activity', icon: 'list', title: '动态' }, { key: 'approvals', icon: 'shield', title: '待确认' }, { key: 'upcoming', icon: 'clock', title: '目标进展' }, { key: 'identity', icon: 'fingerprint', title: '关于助手' }] as { key: string; icon: IconName; title: string }[]).map(tab => <button key={tab.key} className={panelTab === tab.key ? 'selected' : ''} role="tab" aria-selected={panelTab === tab.key} aria-label={tab.title} title={tab.title} onClick={() => setPanelTab(tab.key)}><Icon name={tab.icon} size={17} /></button>)}</div><div className="panel-body" role="tabpanel" aria-label={{ activity: '动态', approvals: '待确认', upcoming: '目标进展', identity: '关于助手' }[panelTab]}>{panelTab === 'activity' && <><div className="panel-section-heading"><h3>{recentActivity.length ? formatDate(recentActivity[0].createdAt) : '今天'}</h3>{recentActivity.length > 0 && <button onClick={() => navigate('activity')}>全部<Icon name="chevron" size={12} /></button>}</div>{recentActivity.length ? <ActivityList activity={recentActivity.slice(0, 8)} compact onOpen={(conversationId, goalId) => goalId ? navigate('goals', goalId) : conversationId ? navigate('chat', conversationId) : undefined} /> : <div className="panel-empty-row"><span className="activity-icon"><Icon name="list" size={18} /></span><span><strong>暂无动态</strong><p>对话与目标进展会显示在这里</p></span></div>}</>}{panelTab === 'approvals' && <><div className="panel-section-heading"><h3>待你确认</h3><button onClick={() => setDialog({ type: 'management', tab: 'approvals' })}>全部记录</button></div>{pendingApprovals.length ? pendingApprovals.map(approval => <section className="identity-copy" key={approval.id} data-approval-id={approval.id}><ApprovalSummary approval={approval} data={data || undefined} /><div className="modal-actions">{approvalThread(approval) ? <button className="primary-button" onClick={() => navigate('chat', approvalThread(approval))}>在原聊天审阅动作</button> : <><button className="secondary-button" disabled={busy || session.user?.role !== 'admin'} onClick={() => void mutate(`/approvals/${approval.id}/decision`, 'POST', { decision: 'denied', confirmed: true })}>拒绝</button><button className="primary-button" disabled={busy || session.user?.role !== 'admin'} onClick={() => void mutate(`/approvals/${approval.id}/decision`, 'POST', { decision: 'approved', confirmed: true })}>批准此请求</button></>}</div></section>) : <EmptyState icon="shield" title="现在没有待确认事项" description="当前没有本地审批请求。原生工具审批仍由审核过的运行时策略负责。" compact />}</>}{panelTab === 'upcoming' && <><button className="identity-library" onClick={() => setDialog({ type: 'management', tab: 'schedules' })}><Icon name="clock" size={17} />管理定时任务<Icon name="chevron" size={14} /></button><div className="panel-section-heading"><h3>目标进展</h3><button onClick={() => navigate('goals')}>管理<Icon name="chevron" size={12} /></button></div>{activeGoals.length ? activeGoals.map(goal => <button className="panel-goal" key={goal.id} onClick={() => navigate('goals', goal.id)}><Icon name="goals" size={20} /><span><strong>{goal.title}</strong><Status value={goal.status} /></span><Icon name="chevron" size={14} /></button>) : <EmptyState icon="clock" title="给未来留一个目标" description="想学的技能、想养成的习惯，都可以从这里开始。" compact><button className="small-pill" onClick={() => navigate('goals')}>创建目标</button></EmptyState>}</>}{panelTab === 'identity' && <><div className="panel-section-heading"><h3>关于 {settings.name}</h3><button onClick={() => setDialog({ type: 'settings' })}>编辑</button></div><div className="identity-copy"><p>陪你理清想法，把大目标变成具体的下一步。</p><div className="identity-row"><span>模型</span><strong>{data?.runtime.model || settings.model}</strong></div><div className="identity-row"><span>运行方式</span><strong>{data?.runtime.kind === 'deepseek-harness' ? '原生 Harness' : '文字规划与复盘'}</strong></div><div className="identity-row"><span>每次目标步数上限</span><strong>{settings.maxGoalSteps} 步</strong></div><div className="identity-row"><span>已保存的记忆</span><strong>{data?.memories.filter(m => m.category !== 'saved').length || 0} 条</strong></div><button className="identity-library" onClick={() => { setLibraryFilter('preference'); navigate('library'); }}><Icon name="fingerprint" size={17} />查看与管理记忆<Icon name="chevron" size={14} /></button><p className="identity-note">这是企业共享工作空间。业务委托由 AI Worker 管理，模型连接和数据由部署方管理。</p></div></>}</div></aside>}

    {selectedGoal && <GoalDetail goal={selectedGoal} runtimeKind={data?.runtime.kind} busy={busy || readOnly} onClose={() => navigate('goals')} onChat={() => navigate('chat', selectedGoal.conversationId)} onInputs={() => setDialog({ type: 'context', conversationId: selectedGoal.conversationId, ...(selectedGoal.inputContext ? { goalId: selectedGoal.id } : {}) })} inputContext={selectedGoal.inputContext || data?.conversations.find(item => item.id === selectedGoal.conversationId)?.inputContext} onAction={action => void goalAction(selectedGoal, action)} onSave={async (title, description, maxSteps, maxOutputTokens) => { const result = await mutate(`/goals/${selectedGoal.id}`, 'PATCH', { title, description, maxSteps, maxOutputTokens }); if (result) notify('目标已保存'); return !!result; }} activity={recentActivity.filter(item => item.goalId === selectedGoal.id)} configured={!!data?.runtime.configured} onSettings={() => setDialog({ type: 'settings' })} onDelete={() => setDialog({ type: 'delete', kind: 'goal', id: selectedGoal.id, title: selectedGoal.title })} />}
    {dialog?.type === 'context' && data && <TaskContextDialog data={data} conversationId={dialog.conversationId} value={dialog.goalId ? data.goals.find(item => item.id === dialog.goalId)?.inputContext : contextConversation ? contextConversation.inputContext : draftContext} readOnly={readOnly} busy={busy} onClose={closeDialog} onManage={tab => setDialog({ type: 'management', tab })} onSave={async inputContext => { if (dialog.goalId) { if (!await mutate(`/goals/${dialog.goalId}`, 'PATCH', { inputContext })) return false; } else if (dialog.conversationId) { if (!await mutate(`/conversations/${dialog.conversationId}/input-context`, 'PATCH', { inputContext })) return false; } else setDraftContext(inputContext); closeDialog(); notify('任务输入已保存，下次发送或开始目标时使用'); return true; }} onUpload={async (file, content) => { const result = await api<{ artifact: Artifact }>('/artifacts', 'POST', { filename: file.name, content, ...(dialog.conversationId ? { sourceConversationId: dialog.conversationId } : {}), requestId: requestId() }); await refresh(true); return result.artifact; }} />}
    {dialog?.type === 'category' && <Modal title={`创建${dialog.category.label}目标`} onClose={closeDialog} className="category-modal"><h2>创建{dialog.category.label}目标</h2><p>首先，我们会在聊天中一起完善目标，了解你希望达成的结果。你可以随时调整计划，准备好后再点击开始推进。</p><button className="primary-button full-width" onClick={() => void beginCategory(dialog.category)} disabled={busy || readOnly}>{busy ? '正在准备…' : '开始吧'}<Icon name="arrow" size={17} /></button></Modal>}
    {dialog?.type === 'management' && data && <ManagementDialog diagnostics={diagnostics} role={session.user?.role || 'viewer'} data={data} initialTab={dialog.tab} onClose={closeDialog} onRefresh={() => refresh(true)} onNavigate={(page, id) => { closeDialog(); navigate(page, id); }} />}
    {dialog?.type === 'settings' && !data && <Modal title="设置" onClose={closeDialog} className="settings-modal"><h2>设置</h2><p>等待读取当前空间设置。连接失败时，可先查看和刷新诊断。</p><DiagnosticsPanel view={diagnostics} compact /></Modal>}
    {dialog?.type === 'settings' && data && <SettingsDialog diagnostics={diagnostics} session={session} onLogout={async () => { try { await onLogout(); } catch (error) { notify(errorText(error), true); } }} onManage={tab => setDialog({ type: 'management', tab })} settings={settings} runtime={data?.runtime} configured={!!data?.runtime.configured} busy={busy} onClose={closeDialog} onSave={async value => { const result = await mutate('/settings', 'PATCH', value); if (result) { notify('设置已保存'); closeDialog(); } }} />}
    {dialog?.type === 'search' && <SearchDialog data={data} onClose={closeDialog} onNavigate={(page, id) => { closeDialog(); navigate(page, id); }} onMemory={memory => setDialog({ type: 'note', memory })} />}
    {dialog?.type === 'rename' && <RenameDialog conversation={dialog.conversation} busy={busy || readOnly} onClose={closeDialog} onSave={async title => { if (await mutate(`/conversations/${dialog.conversation.id}`, 'PATCH', { title })) closeDialog(); }} />}
    {dialog?.type === 'delete' && <Modal title="确认删除" onClose={closeDialog} className="confirm-modal"><span className="confirmation-icon"><Icon name="trash" size={25} /></span><h2>删除{dialog.kind === 'conversation' ? '这段聊天' : dialog.kind === 'goal' ? '这个目标' : '这条笔记'}？</h2><p>“{dialog.title}”将被删除。{dialog.kind === 'conversation' ? '其中的消息和关联目标也会一起删除。' : ''}此操作无法撤销。</p><div className="modal-actions"><button className="secondary-button" onClick={closeDialog}>保留</button><button className="danger-button" disabled={busy || readOnly} onClick={async () => { const result = await mutate(`/${dialog.kind === 'conversation' ? 'conversations' : dialog.kind === 'goal' ? 'goals' : 'memories'}/${dialog.id}`, 'DELETE'); if (result) { if (dialog.kind === 'conversation' && route.id === dialog.id) navigate('chat'); if (dialog.kind === 'goal' && route.id === dialog.id) navigate('goals'); closeDialog(); notify('已删除'); } }}>确认删除</button></div></Modal>}
    {dialog?.type === 'note' && <NoteDialog memory={dialog.memory} busy={busy} readOnly={readOnly} onClose={closeDialog} conversations={conversations} onSave={async (content, category, enabled, conversationId) => { const result = await mutate(dialog.memory ? `/memories/${dialog.memory.id}` : '/memories', dialog.memory ? 'PATCH' : 'POST', { content, category, enabled, conversationId }); if (result) { closeDialog(); notify('已保存到资料库'); } }} />}
    {toast && <div className={`toast ${toast.error ? 'toast-error' : ''}`} role={toast.error ? 'alert' : 'status'}><Icon name={toast.error ? 'info' : 'check'} size={17} />{toast.message}</div>}
  </div>;
}

function ActivityList({ activity, compact = false, onOpen }: { activity: Bootstrap['activity']; compact?: boolean; onOpen: (conversationId?: string, goalId?: string) => void }) { let lastDate = ''; return <div className={`activity-list ${compact ? 'compact-activity' : ''}`}>{activity.map(item => { const date = formatDate(item.createdAt); const showDate = date !== lastDate; lastDate = date; const icon: IconName = item.type.includes('fail') || item.type.includes('block') ? 'info' : item.type.includes('goal') ? 'goals' : item.type.includes('memor') ? 'bookmark' : item.type.includes('message') || item.type.includes('chat') || item.type.includes('conversation') ? 'chat' : 'check'; return <div key={item.id}>{showDate && !compact && <h3 className="activity-date">{date}</h3>}<button className={`activity-item ${!item.goalId && !item.conversationId ? 'not-clickable' : ''}`} onClick={() => onOpen(item.conversationId, item.goalId)} disabled={!item.goalId && !item.conversationId}><span className="activity-icon"><Icon name={icon} size={18} /></span><span className="activity-copy"><strong>{item.title}</strong>{item.detail && <p>{item.detail}</p>}<small>{compact ? `${date} · ` : ''}{formatTime(item.createdAt)}</small></span>{!compact && (item.goalId || item.conversationId) && <Icon name="chevron" size={15} />}</button></div>; })}</div>; }

function SettingsDialog({ settings, runtime, configured, busy, onClose, onSave, diagnostics, onManage, session, onLogout }: { diagnostics: DiagnosticsView; settings: Settings; runtime?: Runtime; configured: boolean; busy: boolean; onClose: () => void; onSave: (settings: Partial<Settings>) => Promise<void>; onManage: (tab: ManagementTab) => void; session: Session; onLogout: () => Promise<void> }) {
  const models = [...new Set((runtime?.models ?? [runtime?.model, settings.model]).filter((model): model is string => !!model && model !== 'not-configured'))];
  const [value, setValue] = useState({ ...settings, model: models.includes(settings.model) ? settings.model : models[0] || '' });
  const [loggingOut, setLoggingOut] = useState(false);
  const logoutLock = useRef(false);
  const canManage = session.user?.role === 'admin';
  return <Modal title="设置" onClose={onClose} className="settings-modal"><div className="modal-heading"><span className="eyebrow">让这里更像你的空间</span><h2>设置</h2></div><form onSubmit={e => { e.preventDefault(); void onSave({ name: value.name, language: value.language, maxGoalSteps: value.maxGoalSteps, ...(models.includes(value.model) ? { model: value.model } : {}) }); }}><section className="settings-section"><h3>你的助手</h3><label className="field-label">名字<input disabled={!canManage} required autoFocus maxLength={40} value={value.name} onChange={e => setValue({ ...value, name: e.target.value })} placeholder="给助手一个名字" /></label><div className="field-grid"><label className="field-label">对话模型<select disabled={!canManage || runtime?.kind === 'deepseek-harness' || models.length < 2} value={value.model} onChange={e => setValue({ ...value, model: e.target.value as Settings['model'] })}>{!models.length && <option value="">请由部署管理员配置模型</option>}{models.map(model => <option key={model} value={model}>{model}</option>)}</select></label><label className="field-label">目标步数上限<select disabled={!canManage} value={value.maxGoalSteps} onChange={e => setValue({ ...value, maxGoalSteps: Number(e.target.value) })}>{Array.from({ length: 8 }, (_, i) => <option key={i + 1} value={i + 1}>{i + 1} 步</option>)}</select></label></div><p className="field-help">助手每次最多推进指定步数，你可以随时暂停或取消。</p></section><section className="settings-section connection-section"><DiagnosticsPanel view={diagnostics} compact onManage={onManage} />{runtime?.kind === 'deepseek-harness' && <p className="field-help">当前运行原生 Harness 模式（{runtime.model}）。模型与工具由服务端经过审核的配置决定。</p>}{!configured && <p className="field-help">请由部署管理员完成所选提供方配置，凭据只在服务端安全录入，不会在这里显示。</p>}</section><section className="settings-section"><h3>空间管理</h3><div className="settings-management-links">{([['capabilities', '运行能力'], ['skills', '技能'], ['connectors', '连接器'], ['schedules', '定时任务'], ['runs', '运行记录'], ['artifacts', '文件产物'], ['approvals', '审批记录']] as [ManagementTab, string][]).map(([tab, label]) => <button type="button" key={tab} onClick={() => onManage(tab)}>{label}<Icon name="chevron" size={14} /></button>)}</div></section><div className="settings-privacy"><Icon name="shield" size={17} /><p>聊天、目标和笔记保存在你部署的服务中。连接模型后，对话上下文与相关记忆会发送给当前配置的模型提供方以生成回复。</p></div><button type="submit" className="primary-button full-width" disabled={busy || !canManage || !value.name.trim()}>{busy ? '正在保存…' : '保存设置'}</button></form>{session.mode === 'enterprise' && <section className="settings-session"><p>当前身份：{session.user?.id} · {session.user?.role}</p><p>会话期限：{session.expiresAt ? new Date(session.expiresAt).toLocaleString() : '由部署方管理'}</p><button type="button" className="secondary-button" disabled={loggingOut} onClick={async () => { if (logoutLock.current) return; logoutLock.current = true; setLoggingOut(true); try { await onLogout(); } finally { logoutLock.current = false; setLoggingOut(false); } }}>{loggingOut ? '正在退出…' : '退出共享空间'}</button></section>}</Modal>;
}
function RenameDialog({ conversation, busy, onClose, onSave }: { conversation: Conversation; busy: boolean; onClose: () => void; onSave: (title: string) => Promise<void> }) { const [title, setTitle] = useState(conversation.title); return <Modal title="重命名聊天" onClose={onClose}><h2>重命名聊天</h2><p>一个容易找到的名字，方便下次继续。</p><form onSubmit={e => { e.preventDefault(); void onSave(title.trim()); }}><label className="field-label">聊天名称<input autoFocus value={title} onChange={e => setTitle(e.target.value)} maxLength={160} required /></label><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>取消</button><button className="primary-button" disabled={busy || !title.trim()}>保存</button></div></form></Modal>; }
function NoteDialog({ memory, conversations, busy, readOnly, onClose, onSave }: { memory?: Memory; conversations: Conversation[]; busy: boolean; readOnly: boolean; onClose: () => void; onSave: (content: string, category: string, enabled: boolean, conversationId: string | null) => Promise<void> }) { const [content, setContent] = useState(memory?.content || ''); const [category, setCategory] = useState(memory?.category || 'saved'); const [enabled, setEnabled] = useState(memory?.enabled !== false); const [scope, setScope] = useState(memory?.conversationId || ''); return <Modal title={memory ? '编辑笔记' : '新建笔记'} onClose={onClose} className="note-modal"><div className="modal-heading"><span className="eyebrow">把值得的事留下</span><h2>{memory ? '编辑笔记' : '新建笔记'}</h2></div><form onSubmit={e => { e.preventDefault(); void onSave(content.trim(), category, enabled, scope || null); }}><div className="note-type-toggle"><button type="button" className={category === 'saved' ? 'selected' : ''} onClick={() => setCategory('saved')}><Icon name="bookmark" size={16} />保存的内容</button><button type="button" className={category !== 'saved' ? 'selected' : ''} onClick={() => setCategory('preference')}><Icon name="fingerprint" size={16} />助手记忆</button></div>{category !== 'saved' && <div className="memory-controls"><label className="management-checkbox"><input type="checkbox" checked={enabled} onChange={e => setEnabled(e.target.checked)} aria-label="启用此记忆" />在适用对话中启用此记忆</label><label className="field-label">记忆范围<select aria-label="记忆范围" value={scope} onChange={e => setScope(e.target.value)}><option value="">整个共享空间</option>{memory?.conversationId && !conversations.some(c => c.id === memory.conversationId) && <option value={memory.conversationId}>原聊天已移除（保存前请选择范围）</option>}{conversations.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}</select></label></div>}<textarea autoFocus className="note-editor" value={content} onChange={e => setContent(e.target.value)} placeholder={category === 'saved' ? '一个想法、一段摘录，或任何你想保存的内容…' : '写下你希望助手记住的偏好和背景…'} required maxLength={20000} aria-label="笔记内容" /><p className="field-help">{category === 'saved' ? '内容会保存在资料库，你可以随时编辑或导出。' : '只有启用且匹配范围的记忆才会加入模型上下文。整个空间的授权用户均可读取。请勿保存密码或密钥。'}</p><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>取消</button><button className="primary-button" disabled={busy || readOnly || !content.trim()}>{busy ? '保存中…' : readOnly ? '仅可查看' : '保存'}</button></div></form></Modal>; }
function SearchDialog({ data, onClose, onNavigate, onMemory }: { data: Bootstrap | null; onClose: () => void; onNavigate: (page: Page, id: string) => void; onMemory: (memory: Memory) => void }) { const [query, setQuery] = useState(''); const normalized = query.trim().toLowerCase(); const conversations = sortNewest(data?.conversations || []).filter(c => !normalized || c.title.toLowerCase().includes(normalized) || data?.messages.some(m => m.conversationId === c.id && m.content.toLowerCase().includes(normalized))).slice(0, 8); const goals = (data?.goals || []).filter(g => normalized && `${g.title} ${g.description}`.toLowerCase().includes(normalized)).slice(0, 5); const memories = (data?.memories || []).filter(m => normalized && m.content.toLowerCase().includes(normalized)).slice(0, 5); return <Modal title="搜索整个空间" onClose={onClose} className="search-modal"><div className="global-search-input"><Icon name="search" size={23} /><input autoFocus placeholder="搜索聊天、目标和笔记…" value={query} onChange={e => setQuery(e.target.value)} aria-label="搜索整个空间" /><kbd>ESC</kbd></div><div className="search-results">{!!conversations.length && <section><h3>{normalized ? '聊天' : '最近聊天'}</h3>{conversations.map(c => <button className="search-result" key={c.id} onClick={() => onNavigate('chat', c.id)}><Icon name="chat" size={19} /><span><strong>{c.title}</strong><small>{formatDate(c.updatedAt)}</small></span><Icon name="chevron" size={15} /></button>)}</section>}{!!goals.length && <section><h3>目标</h3>{goals.map(g => <button className="search-result" key={g.id} onClick={() => onNavigate('goals', g.id)}><Icon name="goals" size={19} /><span><strong>{g.title}</strong><small>{statusLabels[g.status]}</small></span><Icon name="chevron" size={15} /></button>)}</section>}{!!memories.length && <section><h3>资料库</h3>{memories.map(m => <button className="search-result" key={m.id} onClick={() => onMemory(m)}><Icon name="bookmark" size={19} /><span><strong>{m.content.slice(0, 85)}</strong><small>{formatDate(m.createdAt)}</small></span><Icon name="chevron" size={15} /></button>)}</section>}{!conversations.length && !goals.length && !memories.length && <EmptyState icon="search" title={normalized ? '没有找到相关内容' : '所有想法，都能再找到'} description={normalized ? '换一个关键词，再试试看。' : '搜索你聊过的话题、创建的目标或保存的笔记。'} compact />}</div><div className="search-footer"><span>搜索当前空间内的所有内容</span><span><kbd>⌘</kbd> <kbd>K</kbd> 快速打开</span></div></Modal>; }
function GoalDetail({ goal, runtimeKind, inputContext, onInputs, busy, onClose, onChat, onAction, onSave, activity, configured, onSettings, onDelete }: { goal: Goal; runtimeKind?: Runtime['kind']; inputContext?: InputContext; onInputs: () => void; busy: boolean; onClose: () => void; onChat: () => void; onAction: (action: string) => void; onSave: (title: string, description: string, maxSteps: number, maxOutputTokens: number) => Promise<boolean>; activity: Bootstrap['activity']; configured: boolean; onSettings: () => void; onDelete: () => void }) {
  const detailRef = useRef<HTMLElement>(null); const [editing, setEditing] = useState(false); const [title, setTitle] = useState(goal.title); const [description, setDescription] = useState(goal.description); const [maxSteps, setMaxSteps] = useState(goal.maxSteps || 3); const [maxOutputTokens, setMaxOutputTokens] = useState(goal.maxOutputTokens || (goal.maxSteps || 3) * 1600); const canEdit = goal.status !== 'running';
  useEffect(() => { const previous = document.activeElement as HTMLElement; detailRef.current?.querySelector<HTMLElement>('button')?.focus(); function handleKey(e: KeyboardEvent) { if (e.key === 'Escape' && !document.querySelector('.modal-backdrop')) { e.preventDefault(); onClose(); } if (e.key === 'Tab' && !document.querySelector('.modal-backdrop')) { const items = Array.from(detailRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input, textarea, select') || []); const first = items[0], last = items[items.length - 1]; if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); } } } document.addEventListener('keydown', handleKey); return () => { document.removeEventListener('keydown', handleKey); previous?.focus(); }; }, [goal.id]);
  useEffect(() => { setTitle(goal.title); setDescription(goal.description); setMaxSteps(goal.maxSteps || 3); setMaxOutputTokens(goal.maxOutputTokens || (goal.maxSteps || 3) * 1600); }, [goal.id, goal.title, goal.description, goal.maxSteps, goal.maxOutputTokens]);
  return <div className="detail-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section ref={detailRef} className="goal-detail" role="dialog" aria-modal="true" aria-label="目标详情"><header><button className="text-button" onClick={onClose}><Icon name="back" size={18} />所有目标</button><IconButton icon="close" label="关闭目标详情" onClick={onClose} /></header><div className="goal-detail-body"><span className="detail-goal-icon"><Icon name="goals" size={32} /></span><Status value={goal.status} />{editing ? <form className="goal-edit-form" onSubmit={async e => { e.preventDefault(); if (await onSave(title.trim(), description.trim(), maxSteps, maxOutputTokens)) setEditing(false); }}><label className="field-label">目标名称<input value={title} onChange={e => setTitle(e.target.value)} autoFocus maxLength={160} required /></label><label className="field-label">具体描述<textarea value={description} onChange={e => setDescription(e.target.value)} rows={6} placeholder="想实现什么？有什么时间安排或限制？" maxLength={10000} /></label><label className="field-label">本次最多推进<select value={maxSteps} onChange={e => setMaxSteps(Number(e.target.value))}>{Array.from({ length: 8 }, (_, i) => <option value={i + 1} key={i}>{i + 1} 步</option>)}</select></label><label className="field-label">目标终生输出额度<input aria-label="目标输出额度" type="number" min={1600} max={128000} step={1} required value={maxOutputTokens} onChange={e => setMaxOutputTokens(Number(e.target.value))} /></label><p className="field-help">已计入 {goal.outputTokens || 0} tokens。增加额度允许继续推进；额度不是实际账单金额。</p><div className="modal-actions"><button type="button" className="secondary-button" onClick={() => setEditing(false)}>取消</button><button className="primary-button" disabled={busy || !title.trim()}>保存目标</button></div></form> : <><div className="goal-detail-title"><h1>{goal.title}</h1>{canEdit && <IconButton icon="edit" label="编辑目标" onClick={() => setEditing(true)} />}</div><p className="goal-description">{goal.description || '还没有具体描述。你可以先在聊天里梳理想法，或编辑目标，写下你希望达成的结果。'}</p><div className="goal-progress-meta"><span>已推进 <strong>{goal.stepCount || 0}</strong> / {goal.maxSteps || 3} 步</span><span>创建于{formatDate(goal.createdAt)}</span></div><div className="goal-progress-track"><span style={{ width: `${Math.min((goal.stepCount || 0) / (goal.maxSteps || 3) * 100, 100)}%` }} /></div><div className="goal-detail-actions">{goal.status === 'review_required' && <button className="primary-button" disabled={busy} onClick={() => onAction('complete')}><Icon name="check" size={16} />标记已审核</button>}{goal.status === 'running' ? <button className="primary-button" disabled={busy} onClick={() => onAction('pause')}><Icon name="pause" size={16} />暂停目标</button> : ['draft', 'blocked', 'failed', 'paused'].includes(goal.status) ? <button className="primary-button" disabled={busy} onClick={() => onAction(goal.status === 'paused' ? 'resume' : 'start')}><Icon name="play" size={15} />{goal.status === 'paused' ? '继续目标' : goal.status === 'draft' ? '开始推进' : '重试目标'}</button> : null}{goal.conversationId && <button className="secondary-button" onClick={onChat}><Icon name="chat" size={17} />继续聊聊</button>}{!['cancelled', 'completed'].includes(goal.status) && <button className="text-button subdued" disabled={busy} onClick={() => onAction('cancel')}>取消目标</button>}</div>{!configured && !['cancelled', 'completed'].includes(goal.status) && <button className="goal-connection-notice" onClick={onSettings}><Icon name="info" size={18} /><span>目标已保存。连接模型后才能生成计划和推进步骤。</span><Icon name="chevron" size={14} /></button>}{goal.lastError?.message && <div className="goal-error-notice" role="status"><Icon name="info" size={17} /><span>{goal.lastError.message}</span></div>}{goal.output && <section className="goal-output"><h3>{goal.status === 'completed' ? '目标成果 · 已审核' : goal.status === 'review_required' ? '目标成果 · 待你审核' : '阶段性进展'}</h3><MessageContent content={goal.output} /><p>这里是助手生成的文字成果，不代表现实中的目标已经达成。</p></section>}<section className="goal-scope"><button type="button" className="text-button" onClick={onInputs} disabled={busy || goal.status === 'running'}>审阅目标输入 · {inputSummary(inputContext)}</button><h3><Icon name="shield" size={15} />推进范围</h3><p>{runtimeKind === 'deepseek-harness' ? `当前使用原生 Harness。工具和权限由服务端经过人工审核的配置决定；每次最多推进 ${goal.maxSteps || 3} 步。请审核运行记录与产出，界面不会把生成文本视为现实目标已完成。` : `助手会在聊天中分析目标、生成计划与文本成果。每次最多 ${goal.maxSteps || 3} 步，不会调用外部应用、自动发送消息或进行交易。`}</p></section><section className="goal-history"><h2>目标动态</h2>{activity.length ? <ActivityList activity={activity} compact onOpen={() => {}} /> : <p className="muted">准备好时，就从第一步开始。</p>}</section><button className="goal-delete text-button" onClick={onDelete}><Icon name="trash" size={14} />删除目标</button></>}</div></section></div>;
}
